const base = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const jwt = '<REDACTED_SUPABASE_JWT>';
const H = { apikey: jwt, Authorization: 'Bearer ' + jwt };
const labeled = await this.helpers.httpRequest({ method: 'GET', url: base + '/post_feedback?select=activity_id,company,verdict,updated_at&verdict=in.(up,down)', headers: H, json: true });
const existing = await this.helpers.httpRequest({ method: 'GET', url: base + '/poi_vectors?select=activity_id,verdict', headers: H, json: true });
const existMap = new Map();
for (const e of (existing || [])) existMap.set(String(e.activity_id), e.verdict);
const labeledSet = new Set((labeled || []).map(l => String(l.activity_id)));
const pending = [];
for (const l of (labeled || [])) {
  const id = String(l.activity_id);
  if (!existMap.has(id) || existMap.get(id) !== l.verdict) pending.push(l);
}
const purge = [];
for (const id of existMap.keys()) if (!labeledSet.has(id)) purge.push(id);
for (let i = 0; i < purge.length; i += 100) {
  const chunk = purge.slice(i, i + 100);
  const list = chunk.map(x => encodeURIComponent(x)).join(',');
  await this.helpers.httpRequest({ method: 'DELETE', url: base + '/poi_vectors?activity_id=in.(' + list + ')', headers: H, json: true });
}
if (!pending.length) return [];
const textMap = new Map();
const pendIds = pending.map(p => String(p.activity_id));
for (let i = 0; i < pendIds.length; i += 100) {
  const chunk = pendIds.slice(i, i + 100);
  const list = chunk.map(x => encodeURIComponent(x)).join(',');
  const rows = await this.helpers.httpRequest({ method: 'GET', url: base + '/linkedin_posts?select=activity_id,text,companyName&activity_id=in.(' + list + ')', headers: H, json: true });
  for (const r of (rows || [])) textMap.set(String(r.activity_id), { text: r.text, companyName: r.companyName });
}
const out = [];
for (const p of pending) {
  const id = String(p.activity_id);
  const info = textMap.get(id);
  if (!info || !info.text || !String(info.text).trim()) continue;
  out.push({ json: { activity_id: p.activity_id, company: p.company || info.companyName || null, verdict: p.verdict, text: info.text } });
}
return out;

const base = 'https://addwjngdezmmnxddulll.supabase.co/rest/v1';
const jwt = '<REDACTED_SUPABASE_JWT>';
const H = { apikey: jwt, Authorization: 'Bearer ' + jwt, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates,return=minimal' };
const items = $input.all();
const pend = $('Fetch Pending').all();
const rows = [];
const now = new Date().toISOString();
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const emb = resp && resp.data && resp.data[0] && resp.data[0].embedding;
  if (!emb || !Array.isArray(emb)) continue;
  const src = pend[i] && pend[i].json;
  if (!src) continue;
  rows.push({ activity_id: src.activity_id, company: src.company, verdict: src.verdict, post_text: src.text, embedding: '[' + emb.join(',') + ']', updated_at: now });
}
for (let i = 0; i < rows.length; i += 50) {
  const chunk = rows.slice(i, i + 50);
  await this.helpers.httpRequest({ method: 'POST', url: base + '/poi_vectors?on_conflict=activity_id', headers: H, body: chunk, json: true });
}
return [{ json: { embedded: rows.length } }];
